                const int sc = idx % (TILE_W + 2);
                smem[sr][sc] = __ldg(in_ptr + (in_row0 + sr) * W_in + (in_col0 + sc));
            }
        } else {
            #pragma unroll 4
            for (int idx = tid; idx < smem_elems; idx += num_threads) {
                const int sr = idx / (TILE_W + 2);
                const int sc = idx % (TILE_W + 2);
                const int gr = in_row0 + sr;
                const int gc = in_col0 + sc;
                float val = 0.0f;
                if ((unsigned)gr < (unsigned)H_in && (unsigned)gc < (unsigned)W_in)
                    val = __ldg(in_ptr + gr * W_in + gc);
                smem[sr][sc] = val;
            }
        }

        __syncthreads();

        const int out_row = tile_row0 + ty;
        if (out_row < H_out) {
            const float* row0 = smem[ty    ];
            const float* row1 = smem[ty + 1];
            const float* row2 = smem[ty + 2];

            if (out_col0 < W_out) {
                float sum0;
                sum0  = w00 * row0[sx0  ] + w01 * row0[sx0+1] + w02 * row0[sx0+2];
                sum0 += w10 * row1[sx0  ] + w11 * row1[sx0+1] + w12 * row1[sx0+2];
                sum0 += w20 * row2[sx0  ] + w21 * row2[sx0+1] + w22 * row2[sx0+2];
                if (has_bias) sum0 += bias_val;
                output[out_base + out_row * W_out + out_col0] = sum0;
            }
            if (out_col1 < W_out) {
                float sum1;
                sum1  = w00 * row0[sx1  ] + w01 * row0[sx1+1] + w02 * row0[sx1+2];
                sum1 += w10 * row1[sx1  ] + w11 * row1[sx1+1] + w12 * row1[sx1+2];
                sum1 += w20 * row2[sx1  ] + w21 * row2[sx1+1] + w22 * row2[sx1+2];
                if (has_bias) sum1 += bias_val;
                output[out_base + out_row * W_out + out_col1] = sum1;
            }
        }
    }

    // ----------------------------------------------------------------
    // TILE 1: output rows [tile_pair_row + TILE_H, tile_pair_row + 2*TILE_H)
    // Skip entirely if the second tile's first row is already out of range.
    // ----------------------------------------------------------------
    const int tile_row1 = tile_pair_row + TILE_H;
    if (tile_row1 < H_out) {
        // Carry the bottom 2 halo rows of tile 0's smem into the top 2 rows
        // for tile 1. Those correspond to smem rows [TILE_H, TILE_H+1] which
        // held input rows [tile_pair_row+TILE_H, tile_pair_row+TILE_H+1].
        // We need to move them to smem rows [0, 1].
        // Each thread copies a couple of elements to cover all SMEM_W columns.
        //
        // Use the tid to spread the copy across SMEM_W*(+1 col pad excluded)
        // actual halo width is TILE_W+2.
        const int carry_elems = 2 * (TILE_W + 2);
        for (int idx = tid; idx < carry_elems; idx += num_threads) {
            const int sr = idx / (TILE_W + 2);  // 0 or 1
            const int sc = idx % (TILE_W + 2);
            smem[sr][sc] = smem[TILE_H + sr][sc];
        }

        // Now load the new 16 input rows (rows 2..TILE_H+1 of smem) from global
        // memory. Those correspond to input rows [tile_row1+2, tile_row1+TILE_H+1].
        // Combined with carry we need smem rows [0..TILE_H+1] covering input
        // rows [tile_row1, tile_row1+TILE_H+1].
        // in_row0 for tile1 = tile_row1; smem rows 0,1 are already filled from carry.
        const int in_row1 = tile_row1;
        const int new_elems = TILE_H * (TILE_W + 2);  // rows 2..TILE_H+1
        const bool interior1 = ((in_row1 + SMEM_H - 1) < H_in) & ((in_col0 + TILE_W + 1) < W_in);
        if (interior1) {
            #pragma unroll 4
            for (int idx = tid; idx < new_elems; idx += num_threads) {
                const int sr = idx / (TILE_W + 2) + 2;  // smem rows 2..TILE_H+1
                const int sc = idx % (TILE_W + 2);
                smem[sr][sc] = __ldg(in_ptr + (in_row1 + sr) * W_in + (in_col0 + sc));
            }
        } else {
            #pragma unroll 4
            for (int idx = tid; idx < new_elems; idx += num_threads) {
                const int sr = idx / (TILE_W + 2) + 2;
                const int sc = idx % (TILE_W + 2);
                const int gr = in_row1 + sr;
                const int gc = in_col0 + sc;
                float val = 0.0f;
                if ((unsigned)gr < (unsigned)H_in && (unsigned)gc < (unsigned)W_in)
                    val = __ldg(in_ptr + gr * W_in + gc);
                smem[sr][sc] = val;
            }
        }

        __syncthreads();

        const int out_row = tile_row1 + ty;
        if (out_row < H_out) {
            const float* row0 = smem[ty    ];
            const float* row1 = smem[ty + 1];
            const float* row2 = smem[ty + 2];

            if (out_col0 < W_out) {
                float sum0;
                sum0  = w00 * row0[sx0  ] + w01 * row0[sx0+1] + w02 * row0[sx0+2];
                sum0 += w10 * row1[sx0  ] + w11 * row1[sx0+1] + w12 * row1[sx0+2];
                sum0 += w20 * row2[sx0  ] + w21 * row2[sx0+1] + w22 * row2[sx0+2];
                if (has_bias) sum0 += bias_val;
                output[out_base + out_row * W_out + out_col0] = sum0;
            }
            if (out_col1 < W_out) {
                float sum1;
                sum1  = w00 * row0[sx1  ] + w01 * row0[sx1+1] + w02 * row0[sx1+2];
                sum1 += w10 * row1[sx1  ] + w11 * row1[sx1+1] + w12 * row1[sx1+2];
                sum1 += w20 * row2[sx1  ] + w21 * row2[sx1+1] + w22 * row2[sx1+2];
                if (has_bias) sum1 += bias_val;
                output[out_base + out_row * W_out + out_col1] = sum1;
            }
        }
    }
}

torch::Tensor depthwise_conv3x3_s1_p0_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.dim() == 4, "x must be 4D");
    TORCH_CHECK(weight.is_cuda() && weight.is_contiguous(), "weight must be contiguous CUDA tensor");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D");

    const int N     = x.size(0);
    const int C     = x.size(1);
    const int H     = x.size(2);
    const int W     = x.size(3);
    const int H_out = H - 2;
    const int W_out = W - 2;

    TORCH_CHECK(H_out > 0 && W_out > 0, "Input spatial dims too small for 3x3 kernel with no padding");

    auto output = torch::empty({N, C, H_out, W_out}, x.options());
    const bool has_bias = (bias.numel() > 0);

    dim3 block(THREAD_W, THREAD_H);
    // grid.y now covers pairs of TILE_H rows
    dim3 grid(
        (W_out + TILE_W - 1) / TILE_W,
        (H_out + 2 * TILE_H - 1) / (2 * TILE_H),
        N * C
    );

    depthwise_conv3x3_s1_p0_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N, C, H, W, H_out, W_out,
        has_bias
    );

    return output;
}
